<?php
use App\Models\Announcement; use Livewire\Attributes\Computed; use Livewire\Attributes\Title; use Livewire\Component;
new #[Title('ព័ត៌មានក្រុមហ៊ុន')] class extends Component {
 #[Computed] public function items(){ $e=auth()->user()->employee; return Announcement::query()->whereNotNull('published_at')->where('published_at','<=',now())->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->where(function($q)use($e){$q->where('audience_type','all');if($e?->branch_id)$q->orWhere(fn($x)=>$x->where('audience_type','branch')->where('branch_id',$e->branch_id));if($e?->department_id)$q->orWhere(fn($x)=>$x->where('audience_type','department')->where('department_id',$e->department_id));})->orderByDesc('is_pinned')->latest('published_at')->get();}
}; ?>
<div class="space-y-6"><div><flux:heading size="xl">ព័ត៌មានក្រុមហ៊ុន</flux:heading><flux:subheading>សេចក្តីជូនដំណឹងសម្រាប់អ្នក</flux:subheading></div><div class="grid gap-4 lg:grid-cols-2">@forelse($this->items as $x)<article class="rounded-2xl border border-zinc-200 bg-white p-6 dark:border-zinc-700 dark:bg-zinc-900"><div class="flex items-start justify-between gap-3"><flux:heading>{{$x->title}}</flux:heading>@if($x->is_pinned)<flux:badge color="amber">សំខាន់</flux:badge>@endif</div><div class="mt-4 whitespace-pre-line text-sm leading-7 text-zinc-700 dark:text-zinc-300">{{$x->content}}</div><div class="mt-4 text-xs text-zinc-500">{{$x->published_at->format('d/m/Y H:i')}}</div></article>@empty<div class="text-zinc-500">មិនមានសេចក្តីជូនដំណឹងថ្មី។</div>@endforelse</div></div>
